import React, { useEffect, useState } from "react";
import './styles/TaskCard.css'

export default function TaskCard({ task, onDelete, onUpdate, people, setComments }) {
  const [edited, setEdited] = useState({ ...task });
  const [newComment, setNewComment] = useState("");
  const user = sessionStorage.getItem('internal-vault-user');

  const handleChange = (field, value) => {
    setEdited(prev => ({ ...prev, [field]: value }));
  };

  useEffect(()=>{
    handleBlur();
  },[edited]);

  const handleBlur = () => {
    if (JSON.stringify(edited) !== JSON.stringify(task)) {
      onUpdate(edited.id, edited);
    }
  };

  const handleComment = () => {
    let userx = user;
    try {
      userx = JSON.parse(user).nickname;
    } catch (error) {
      userx = user.nickname;
      console.error(error);
    }
    if (newComment.trim()) {
      const commentObj = {
        id: Date.now(), // unique id
        text: newComment.trim(),
        timestamp: new Date().toISOString(),
        username: userx
      };

      setEdited((prev) => ({
        ...prev,
        feedback: [...(prev.feedback || []), commentObj],
      }));

      setNewComment(""); // clear input
    }
  };

  const handleDeleteComment = (id) => {
    setEdited((prev) => ({
      ...prev,
      feedback: (prev.feedback || []).filter((c) => c.id !== id),
    }));
  };

  return (
    <div className="rl-task-card">
      <div className="rl-task-header">
        <input
          className="rl-task-input"
          value={edited.title}
          onChange={(e) => handleChange("title", e.target.value)}
          onBlur={handleBlur}
        />
        <button onClick={onDelete} title="Delete Task">
          <i className="fa fa-trash"></i>
        </button>
      </div>
      <details className="rlfb-container">
          <summary className="rlfb-summary"></summary>
              <div>
                <textarea
                    className="rl-task-description"
                    value={edited.description}
                    onChange={(e) => handleChange("description", e.target.value)}
                    onBlur={handleBlur}
                  />

                  <div className="rl-task-meta">
                    <select
                      className="rl-task-select"
                      value={edited.assignee}
                      onChange={(e) => handleChange("assignee", e.target.value)}
                      onBlur={handleBlur}
                    >
                      {people.map((p) => (
                        <option key={p}>{p}</option>
                      ))}
                    </select>

                    <select
                      className="rl-task-select"
                      value={edited.status}
                      onChange={(e) => handleChange("status", e.target.value)}
                      onBlur={handleBlur}
                    >
                      {["Backlog", "To Do", "In Progress", "Done"].map((s) => (
                        <option key={s}>{s}</option>
                      ))}
                    </select>

                    <input
                      type="date"
                      className="rl-task-select"
                      value={edited.dueDate || ""}
                      onChange={(e) => handleChange("dueDate", e.target.value)}
                      onBlur={handleBlur}
                    />
                    
                  </div>
                  <details className="rlfb-container">
                      <summary className="rlfb-summary">Feedback</summary>
                      <div className="rlfb-body">
                        <ul className="rlfb-list">
                          {(task.feedback || []).map((comment) => (
                            <li key={comment.id} className="rlfb-item">
                              <div className="rlfb-meta">
                                <span className="rlfb-username">{comment.username}</span>
                                <span className="rlfb-timestamp">
                                  {new Date(comment.timestamp).toLocaleString()}
                                </span>
                              </div>

                              <p className="rlfb-text">{comment.text}</p>

                              <button
                                className="rlfb-delete-btn"
                                onClick={() => handleDeleteComment(comment.id)}
                                title="Delete comment"
                              >
                                <i className="fa fa-trash"></i>
                              </button>
                            </li>

                          ))}
                        </ul>

                        <div className="rlfb-input-row">
                          <input
                            type="text"
                            className="rlfb-input"
                            value={newComment}
                            onChange={(e) => setNewComment(e.target.value)}
                            placeholder="Write feedback..."
                          />
                          <button className="rlfb-send-btn" onClick={handleComment}>
                            Send
                          </button>
                        </div>
                      </div>
                    </details>
              </div>
        </details>
      
    </div>
  );
}
